#!/usr/bin/env node
/* global console, process */
// Presentation fidelity vectors are generated by the Java tests (java/src/test/resources/fx/vectors/) and
// mirrored here (test/fx/vectors/) so each edition's CI is self-contained (docs/architecture/animation.md §3.4).
//   node tools/sync-fx-vectors.mjs          # check (no-op without a ../java checkout)
//   node tools/sync-fx-vectors.mjs --write  # copy Java → Bedrock
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SRC = path.resolve(ROOT, '../java/src/test/resources/fx/vectors');
const DST = path.join(ROOT, 'test/fx/vectors');
if (!fs.existsSync(SRC)) {
  console.info('no ../java checkout: vector sync skipped');
  process.exit(0);
}
const write = process.argv.includes('--write');
let diff = 0;
for (const f of fs.readdirSync(SRC).filter((n) => n.endsWith('.json'))) {
  const a = fs.readFileSync(path.join(SRC, f));
  const dst = path.join(DST, f);
  if (fs.existsSync(dst) && fs.readFileSync(dst).equals(a)) continue;
  if (write) {
    fs.mkdirSync(DST, { recursive: true });
    fs.writeFileSync(dst, a);
    console.info(`synced ${f}`);
  } else {
    console.error(`out of sync: ${f}`);
    diff++;
  }
}
if (diff) process.exit(1);
console.info('fx vectors in sync');
